/**
 * The endpoint catalog is generated by `npm run catalog` (scripts/build-catalog.mjs) and code-split
 * into its own chunk. `loadCatalog()` must resolve before the app renders.
 */
import type { Catalog, Endpoint, Platform } from '../lib/types';

let catalog: Catalog | null = null;
let byId = new Map<string, Endpoint>();
let platformById = new Map<string, Platform>();

export async function loadCatalog(): Promise<Catalog> {
  if (catalog) return catalog;
  const mod = await import('./catalog.json');
  catalog = mod.default as unknown as Catalog;
  byId = new Map(catalog.endpoints.map((e) => [e.id, e]));
  platformById = new Map(catalog.platforms.map((p) => [p.id, p]));
  return catalog;
}

export function getCatalog(): Catalog {
  if (!catalog) throw new Error('Catalog not loaded');
  return catalog;
}

export function findEndpoint(id: string | undefined | null): Endpoint | undefined {
  return id ? byId.get(id) : undefined;
}

export function platformTitle(id: string): string {
  return platformById.get(id)?.title ?? id;
}

/** Category labels as shown in filters. */
export const CATEGORY_LABELS: Record<string, string> = {
  search: 'Search',
  posts: 'Posts',
  profiles: 'Profiles',
  comments: 'Comments',
  products: 'Products',
  ads: 'Ads',
  jobs: 'Jobs',
};
